let _now = now();
fn_current_occupancy()
| project CurrentOccupancy = current_occupancy

let _capacity = toscalar(StoreConfig | take 1 | project max_capacity);
let _now = now() - 5h;
let _occupancy = toscalar(
    officeCam
    | where ts >= startofday(_now) and ts <= _now
    | summarize arg_max(ts, event_type) by track_id
    | summarize CurrentOccupancy = countif(event_type == "PERSON_ENTERED")
);
print CurrentOccupancy = _occupancy,
      MaxCapacity = _capacity,
      OccupancyPct = round(todouble(_occupancy) / todouble(_capacity) * 100.0, 1)

let _now = now() - 5h;
let _today = startofday(_now);
let _today_str = format_datetime(_today, 'yyyy-MM-dd');
let _traffic =
    officeCam
    | where ts >= _today and ts <= _now and event_type == "PERSON_ENTERED"
    | extend h = datetime_part("hour", ts)
    | summarize Visitors = count() by h;
StaffSchedule
| where sched_date == _today_str and sched_hour <= datetime_part("hour", _now)
| join kind=leftouter _traffic on $left.sched_hour == $right.h
| extend Visitors = coalesce(Visitors, 0)
| extend VisitorsPerStaff = round(todouble(Visitors) / todouble(staff_count), 1)
| project Hour = sched_hour, StaffCount = staff_count, Visitors, VisitorsPerStaff, Shift = shift_label
| order by Hour asc

let _now = now();
let _traffic =
    fn_peak_quiet_hours()
    | summarize Visitors = sum(visitors) by Hour = hour_of_day
    | order by Visitors desc;
let _busiest = _traffic | take 1 | extend Label = "Busiest";
let _quietest = _traffic | order by Visitors asc | take 1 | extend Label = "Quietest";
union _busiest, _quietest
| project Label, Hour, Visitors
